export type XinxiangIdentity = "seng" | "dan" | "shi" | "jue";

export interface ZhengquanCandidate {
	hp: number;
	handcardCount: number;
}

export const XINXIANG_IDENTITIES: XinxiangIdentity[] = ["seng", "dan", "shi", "jue"];
export const IDENTITY_SELECTION_TRIGGERS = ["phaseDrawEnd"] as const;
export const JUE_GAIN_TRIGGERS = ["gainAfter", "loseAsyncAfter"] as const;

export type IdentityOpportunityLevels = Record<XinxiangIdentity, number>;

const IDENTITY_AI_ORDER: XinxiangIdentity[] = ["shi", "seng", "jue", "dan"];

export function chooseIdentityByOpportunity(
	legalIdentities: XinxiangIdentity[],
	current: XinxiangIdentity | undefined,
	levels: IdentityOpportunityLevels
): XinxiangIdentity | undefined {
	const legal = IDENTITY_AI_ORDER.filter(identity => legalIdentities.includes(identity));
	if (!legal.length) return undefined;
	const maxLevel = Math.max(...legal.map(identity => levels[identity] ?? 0));
	if (maxLevel > 0) {
		return legal.find(identity => identity !== current && levels[identity] === maxLevel) ?? legal.find(identity => levels[identity] === maxLevel);
	}
	return legal.find(identity => identity !== current) ?? legal[0];
}

export function estimateJueTaxes(ownerHand: number, targetHand: number, extraGainEvents = 0): number {
	let owner = Math.max(0, Math.trunc(ownerHand));
	let target = Math.max(0, Math.trunc(targetHand));
	let taxes = 0;
	const gain = (amount: number) => {
		target += amount;
		if (target > owner) {
			taxes++;
			target--;
			owner++;
		}
	};
	gain(2);
	for (let index = 0; index < Math.max(0, Math.trunc(extraGainEvents)); index++) gain(1);
	return taxes;
}

export function estimateHighestPindianNumber(handcardCount: number): number {
	const count = Math.max(1, Math.trunc(handcardCount));
	return Math.min(13, Math.ceil((13 * count) / (count + 1)));
}

export function getRequiredZhengquanBoost(selfNumber: number, targetNumber: number): number {
	return Math.max(0, Math.trunc(targetNumber) - Math.trunc(selfNumber) + 1);
}

export function shouldUseZhengquan(selfNumber: number, targetHandcardCount: number, ku: number): boolean {
	if (ku <= 0 || selfNumber <= 0 || targetHandcardCount <= 0) return false;
	return getRequiredZhengquanBoost(selfNumber, estimateHighestPindianNumber(targetHandcardCount)) <= ku - 1;
}

const IDENTITY_LABELS: Record<XinxiangIdentity, string> = {
	seng: "僧",
	dan: "旦",
	shi: "士",
	jue: "爵",
};

export function getIdentityLabel(identity: XinxiangIdentity): string {
	return IDENTITY_LABELS[identity];
}

export function getIdentityFromLabel(label: string): XinxiangIdentity | undefined {
	return XINXIANG_IDENTITIES.find(identity => IDENTITY_LABELS[identity] === label);
}

export function getIdentityControls(canChooseJue: boolean): string[] {
	return XINXIANG_IDENTITIES.filter(identity => identity !== "jue" || canChooseJue).map(getIdentityLabel);
}

export function getIdentitySex(identity: XinxiangIdentity): "unknown" | "female" | "male" {
	if (identity === "seng") return "unknown";
	if (identity === "dan") return "female";
	return "male";
}

export interface IdentityRepeatResolution {
	requiresDiscard: boolean;
	requiresDifferentChoice: boolean;
	gainKu: boolean;
}

export function getIdentityRepeatResolution(
	previous: XinxiangIdentity | undefined,
	next: XinxiangIdentity,
	discardedForSameIdentity = false
): IdentityRepeatResolution {
	if (previous === undefined) {
		return { requiresDiscard: false, requiresDifferentChoice: false, gainKu: false };
	}
	if (previous !== next) {
		return { requiresDiscard: false, requiresDifferentChoice: false, gainKu: true };
	}
	return {
		requiresDiscard: true,
		requiresDifferentChoice: !discardedForSameIdentity,
		gainKu: !discardedForSameIdentity,
	};
}

export function canBoostDanDamage(identity: XinxiangIdentity | undefined, targetSex: string, usesThisTurn: number): boolean {
	return identity === "dan" && targetSex === "male" && usesThisTurn < 1;
}

export function canUseSengConversion(identity: XinxiangIdentity | undefined, suit: string, number: number): boolean {
	return identity === "seng" && suit === "heart" && number >= 2 && number <= 9;
}

export function shouldTriggerShi(identity: XinxiangIdentity | undefined, isPhaseUsing: boolean, cardType: string): boolean {
	return identity === "shi" && isPhaseUsing && cardType === "trick";
}

export function shouldLevyJueGain(
	identity: XinxiangIdentity | undefined,
	isChosenTarget: boolean,
	gainedCardCount: number,
	targetHandcardCount: number,
	ownerHandcardCount: number
): boolean {
	return identity === "jue" && isChosenTarget && gainedCardCount > 0 && targetHandcardCount > ownerHandcardCount;
}

export function getPindianBoostControls(ku: number): string[] {
	const count = Math.max(0, Math.trunc(ku));
	return ["不追加", ...Array.from({ length: count }, (_, index) => `${index + 1}枚`)];
}

export function getPindianBoostAmount(control: string, ku: number): number {
	if (control === "不追加") return 0;
	const amount = Number.parseInt(control, 10);
	if (!Number.isFinite(amount)) return 0;
	return Math.max(0, Math.min(Math.trunc(ku), amount));
}

export function getBoostedPindianNumber(baseNumber: number, spentKu: number): number {
	return Math.trunc(baseNumber) + Math.max(0, Math.trunc(spentKu));
}

export function isZhengquanTarget(candidate: ZhengquanCandidate, allPlayers: ZhengquanCandidate[]): boolean {
	if (candidate.handcardCount <= 0 || allPlayers.length === 0) return false;
	const highestHp = Math.max(...allPlayers.map(player => player.hp));
	const mostHandcards = Math.max(...allPlayers.map(player => player.handcardCount));
	return candidate.hp === highestHp || candidate.handcardCount === mostHandcards;
}
